 293	        } catch (ShipmentException e) {
 294	            throw e;
 295	        } catch (Exception e) {
 296	            log.error("운송장 정보 업데이트 실패: shipmentId={}, error={}", shipmentId, e.getMessage(), e);
 297	            throw new ShipmentException(
 298	                    ShipmentErrorCode.SHIPMENT_NOT_FOUND,
 299	                    "운송장 정보 업데이트 중 오류 발생: " + e.getMessage(),
 300	                    e
 301	            );
 302	        }
 303	    }
 304	
 305	    /**
 306	     * 전체 배송 상태를 주기적으로 업데이트합니다.
 307	     */
 308	    @Transactional
 309	    public void updateShipmentStatuses() {
 310	        log.info("전체 배송 상태 업데이트 시작");
 311	
 312	        // 1. IN_TRANSIT 또는 OUT_FOR_DELIVERY 상태의 OrderShipment 조회
 313	        List<OrderShipment> shipments = orderShipmentRepository.findByStatusIn(
 314	                List.of(ShipmentStatus.IN_TRANSIT, ShipmentStatus.OUT_FOR_DELIVERY)
 315	        );
 316	
 317	        log.debug("업데이트 대상 배송 조회: 총 {}건", shipments.size());
 318	
 319	        int successCount = 0;
 320	        int errorCount = 0;
 321	
 322	        for (OrderShipment shipment : shipments) {
 323	            try {
 324	                String trackingNumber = shipment.getTrackingNumber();
 325	                if (trackingNumber == null || trackingNumber.isBlank()) {
 326	                    log.warn("운송장 번호가 없는 배송건 스킵: shipmentId={}", shipment.getId());
 327	                    errorCount++;
 328	                    continue;
 329	                }
 330	
 331	                log.debug("배송 상태 조회 시작: shipmentId={}, trackingNumber={}",
 332	                        shipment.getId(), trackingNumber);
 333	
 334	                // 2. CJ대한통운에서 현재 배송 상태 추출
 335	                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
 336	                ShipmentStatus newStatus = mapToShipmentStatus(currentStatus);
 337	
 338	                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}, newStatus={}",
 339	                        shipment.getId(), currentStatus, newStatus);
 340	
 341	                // 현재 상태와 동일한 경우 중복 처리 방지
 342	                if (shipment.getStatus() == newStatus) {
 343	                    log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
 344	                            shipment.getId(), newStatus);
 345	                    successCount++;
 346	                    continue;
 347	                }
 348	
 349	                // 3. 배송 상태가 DELIVERED인 경우 Order와 Shipment 상태 업데이트
 350	                if (newStatus == ShipmentStatus.DELIVERED) {
 351	                    log.info("배송 완료 처리: shipmentId={}", shipment.getId());
 352	
 353	                    shipment.updateStatus(newStatus);
 354	                    Order order = shipment.getOrder();
 355	                    order.updateStatus(OrderStatus.COMPLETED);
 356	
 357	                    // 배송 완료 알림 전송
 358	                    User buyer = order.getUser();
 359	                    notificationCommandService.createNotification(
 360	                            buyer.getId(),
 361	                            NotificationCategory.SHOPPING,
 362	                            NotificationType.BID,
 363	                            "상품이 배송 완료되었습니다. 주문 ID: " + order.getId()
 364	                    );
 365	
 366	                    log.info("배송 완료 알림 전송: userId={}, orderId={}",
 367	                            buyer.getId(), order.getId());
 368	
 369	                } else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY &&
 370	                        shipment.getStatus() != ShipmentStatus.OUT_FOR_DELIVERY) {
 371	                    log.info("배송 출발 처리: shipmentId={}", shipment.getId());
 372	                    shipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
 373	
 374	                } else {
 375	                    log.debug("기타 상태 업데이트: shipmentId={}, newStatus={}",
 376	                            shipment.getId(), newStatus);
 377	                    shipment.updateStatus(newStatus);
 378	                }
 379	
 380	                orderShipmentRepository.save(shipment);
 381	                successCount++;
 382	
 383	            } catch (Exception e) {
 384	                log.error("배송 상태 업데이트 실패: shipmentId={}, error={}",
 385	                        shipment.getId(), e.getMessage(), e);
 386	                errorCount++;
 387	            }
 388	        }
 389	
 390	        log.info("전체 배송 상태 업데이트 완료: 성공={}건, 실패={}건", successCount, errorCount);
 391	    }
 392	
 393	    /**
 394	     * 배송사 상태 텍스트를 내부 ShipmentStatus로 매핑합니다.
 395	     *
 396	     * @param statusText 배송사 상태 텍스트
 397	     * @return 매핑된 ShipmentStatus
 398	     */
 399	    private ShipmentStatus mapToShipmentStatus(String statusText) {
 400	        return switch (statusText) {
 401	            case "배송완료" -> ShipmentStatus.DELIVERED;
 402	            case "배송출발" -> ShipmentStatus.OUT_FOR_DELIVERY;
 403	            default -> ShipmentStatus.IN_TRANSIT;
 404	        };
 405	    }
 406	
 407	    /**
 408	     * OrderBid와 SaleBid의 상태를 COMPLETED로 업데이트합니다.
 409	     *
 410	     * @param orderId 주문 ID
 411	     */
 412	    @Transactional
 413	    private void updateOrderAndSaleBidStatusToCompleted(Long orderId) {
 414	        log.info("입찰 상태 COMPLETED로 변경: orderId={}", orderId);
 415	
 416	        try {
 417	            // OrderBid 조회
 418	            OrderBid orderBid = orderBidQueryService.findByOrderId(orderId)
 419	                    .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다: " + orderId));
 420	
 421	            // 상태를 COMPLETED로 업데이트
 422	            if (orderBid.getStatus() == com.fream.back.domain.order.entity.BidStatus.MATCHED) {
 423	                log.debug("OrderBid 상태 COMPLETED로 변경: orderBidId={}", orderBid.getId());
 424	                orderBid.updateStatus(com.fream.back.domain.order.entity.BidStatus.COMPLETED);
 425	            }
 426	
 427	            // SaleBid 상태 업데이트
 428	            SaleBid saleBid = saleBidQueryService.findByOrderId(orderId);
 429	            if (saleBid != null && saleBid.getStatus() == BidStatus.MATCHED) {
 430	                log.debug("SaleBid 상태 COMPLETED로 변경: saleBidId={}", saleBid.getId());
 431	                saleBid.updateStatus(BidStatus.COMPLETED);
 432	            }
 433	
 434	            log.info("입찰 상태 COMPLETED 변경 완료: orderId={}", orderId);
 435	
 436	        } catch (Exception e) {
 437	            log.error("입찰 상태 변경 실패: orderId={}, error={}", orderId, e.getMessage(), e);
 438	            // 상태 변경 실패는 로그만 남기고 진행 (주요 로직에 영향 주지 않음)
 439	        }
 440	    }
 441	
 442	    /**
 443	     * 단일 송장에 대해 즉시 상태를 갱신하고, 최종 상태를 반환합니다.
 444	     *
 445	     * @param shipmentId 배송 ID
 446	     * @param courier 택배사
 447	     * @param trackingNumber 운송장 번호
 448	     * @return 갱신된 배송 상태
 449	     * @throws ShipmentException 배송 상태 조회 실패 시 발생
 450	     */
 451	    @Transactional
 452	    public ShipmentStatus updateAndCheckShipmentStatus(Long shipmentId, String courier, String trackingNumber) throws Exception {
 453	        log.info("단일 송장 상태 즉시 조회 및 업데이트: shipmentId={}, courier={}, trackingNumber={}",
 454	                shipmentId, courier, trackingNumber);
 455	
 456	        if (courier == null || courier.isBlank() || trackingNumber == null || trackingNumber.isBlank()) {
 457	            log.warn("유효하지 않은 배송사 또는 운송장 번호: shipmentId={}", shipmentId);
 458	            throw new ShipmentException(ShipmentErrorCode.TRACKING_INFO_REQUIRED);
 459	        }
 460	
 461	        try {
 462	            // 1) 기존 Shipment 로드
 463	            OrderShipment shipment = orderShipmentRepository.findById(shipmentId)
 464	                    .orElseThrow(() -> new ShipmentException(
 465	                            ShipmentErrorCode.SHIPMENT_NOT_FOUND,
 466	                            "Shipment 정보를 찾을 수 없습니다: " + shipmentId
 467	                    ));
 468	
 469	            log.debug("배송 정보 조회 완료: shipmentId={}, 현재상태={}",
 470	                    shipment.getId(), shipment.getStatus());
 471	
 472	            // 2) 송장 정보 업데이트 (택배사, 송장번호)
 473	            shipment.updateTrackingInfo(courier, trackingNumber);
 474	            log.debug("송장 정보 업데이트 완료: courier={}, trackingNumber={}", courier, trackingNumber);
 475	
 476	            // 3) CJ대한통운 조회로 현재 상태 확인
 477	            String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
 478	            ShipmentStatus newStatus = mapToShipmentStatus(currentStatus);
 479	
 480	            log.info("배송 상태 조회 결과: currentStatus={}, mappedStatus={}", currentStatus, newStatus);
 481	
 482	            // 4) 상태에 따른 처리
 483	            if (newStatus == ShipmentStatus.DELIVERED) {
 484	                log.info("배송 완료 처리: shipmentId={}", shipmentId);
 485	
 486	                shipment.updateStatus(ShipmentStatus.DELIVERED);
 487	
 488	                // 주문 완료 로직
 489	                completeOrder(shipment.getOrder().getId());
 490	
 491	            } else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY) {
 492	                log.info("배송 출발 처리: shipmentId={}", shipmentId);
 493	                shipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
 494	
 495	            } else {
 496	                log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
 497	                shipment.updateStatus(ShipmentStatus.IN_TRANSIT);
 498	            }
 499	
 500	            // 5) 상태 반환
 501	            log.info("송장 상태 확인 완료: shipmentId={}, finalStatus={}",
 502	                    shipmentId, shipment.getStatus());
 503	            return shipment.getStatus();
 504	
 505	        } catch (ShipmentException e) {
 506	            throw e;
 507	        } catch (Exception e) {
 508	            log.error("송장 상태 확인 중 오류 발생: shipmentId={}, error={}",
 509	                    shipmentId, e.getMessage(), e);
 510	            throw new ShipmentException(
 511	                    ShipmentErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
 512	                    "배송 상태 조회 중 오류 발생: " + e.getMessage(),
 513	                    e
 514	            );
 515	        }
 516	    }
 517	}

