     5	    IN_TRANSIT,          // 배송 중
     6	    IN_INSPECTION,       // 검수 중
     7	    FAILED_INSPECTION,   // 검수 불합격
     8	    IN_STORAGE,          // 창고 보관 중
     9	    ON_AUCTION,          // 판매 입찰 중
    10	    SELLING,             // 판매중 (등록된 상태)
    11	    SOLD,                // 판매 완료
    12	    AUCTION_EXPIRED;     // 입찰 기한 만료
    14	    // 상태 전환 규칙
    15	    public boolean canTransitionTo(SaleStatus newStatus) {
    16	        return switch (this) {
    17	            case PENDING_SHIPMENT -> newStatus == IN_TRANSIT;
    18	            case IN_TRANSIT -> newStatus == IN_INSPECTION;
    19	            case IN_INSPECTION -> newStatus == FAILED_INSPECTION || newStatus == IN_STORAGE;
    20	            case IN_STORAGE -> newStatus == ON_AUCTION || newStatus == AUCTION_EXPIRED || newStatus == SELLING;
    21	            case ON_AUCTION -> newStatus == SOLD || newStatus == AUCTION_EXPIRED;
    22	            case SELLING -> newStatus == SOLD || newStatus == AUCTION_EXPIRED || newStatus == ON_AUCTION;
    23	            case SOLD, AUCTION_EXPIRED, FAILED_INSPECTION -> false; // SOLD 상태에서는 다른 상태로 전환 불가
    24	        };
    25	    }
